1	/**
2	 * WebMCP Manager
3	 * 管理动态网站工具的注册和执行
4	 */
5	
6	import { siteToolsConfig, matchSiteConfig, SiteConfig, SiteTool } from './site-tools-config';
7	import { getLocalRecordedSiteConfig, getLocalRecordedSiteSummaries } from './recorder';
8	import { NativeMessageType } from 'mcp-chrome-shared';
9	import { emit as emitBusMessage } from '@/entrypoints/background/native-message-bus';
10	
11	// Worldbook API 配置
12	const DEFAULT_WORLDBOOK_API_URL = 'https://worldbook.it.com/api/webmcp';
13	let cachedWorldbookApiUrl: string | null = null;
14	let cachedWorldbookEnabled: boolean | null = null;
15	
16	function getStorage<T extends Record<string, any>>(keys: string[]): Promise<T> {
17	  return new Promise((resolve) => {
18	    chrome.storage.local.get(keys, (result) => resolve(result as T));
19	  });
20	}
21	
22	async function isWorldbookWebMCPEnabled(): Promise<boolean> {
23	  if (cachedWorldbookEnabled !== null) {
24	    return cachedWorldbookEnabled;
25	  }
26	
27	  try {
28	    const result = await getStorage<{ worldbookWebMCPEnabled?: boolean }>([
29	      'worldbookWebMCPEnabled',
30	    ]);
31	    // Default to true
32	    cachedWorldbookEnabled = result.worldbookWebMCPEnabled !== false;
33	    return cachedWorldbookEnabled;
34	  } catch (error) {
35	    console.log('[WebMCP] Failed to read Worldbook WebMCP preference:', error);
36	    return true; // Enable by default
37	  }
38	}
39	
40	async function getWorldbookApiUrl(): Promise<string> {
41	  if (cachedWorldbookApiUrl) {
42	    return cachedWorldbookApiUrl;
43	  }
44	
45	  try {
46	    const result = await getStorage<{ webmcpApiUrl?: string; worldbookApiUrl?: string }>([
47	      'webmcpApiUrl',
48	      'worldbookApiUrl',
49	    ]);
50	    const candidate = (result.webmcpApiUrl || result.worldbookApiUrl || '').trim();
51	    if (candidate) {
52	      cachedWorldbookApiUrl = candidate;
53	      return cachedWorldbookApiUrl;
54	    }
55	  } catch (error) {
56	    console.log('[WebMCP] Failed to read Worldbook API override from storage:', error);
57	  }
58	
59	  cachedWorldbookApiUrl = DEFAULT_WORLDBOOK_API_URL;
60	  return cachedWorldbookApiUrl;
61	}
62	
63	chrome.storage.onChanged.addListener((changes, areaName) => {
64	  if (areaName !== 'local') return;
65	  if (changes.webmcpApiUrl || changes.worldbookApiUrl) {
66	    const next = (
67	      (changes.webmcpApiUrl?.newValue as string | undefined) ||
68	      (changes.worldbookApiUrl?.newValue as string | undefined) ||
69	      ''
70	    ).trim();
71	    cachedWorldbookApiUrl = next || DEFAULT_WORLDBOOK_API_URL;
72	  }
73	  if (changes.worldbookWebMCPEnabled !== undefined) {
74	    cachedWorldbookEnabled = changes.worldbookWebMCPEnabled.newValue !== false;
75	    console.log(`[WebMCP] Worldbook WebMCP preference changed to: ${cachedWorldbookEnabled}`);
76	  }
77	});
78	
79	// Debounce timeout for native server notification
80	let notifyNativeTimeout: ReturnType<typeof setTimeout> | null = null;
81	
82	/**
83	 * Send WebMCP tools update to native server
84	 */
85	function notifyNativeServerToolsUpdate(
86	  action: 'register' | 'unregister',
87	  tabId: number,
88	  siteName?: string,
89	  tools?: SiteTool[],
90	) {
91	  // Debounce to prevent rapid fire
92	  if (notifyNativeTimeout) {
93	    clearTimeout(notifyNativeTimeout);
94	  }
95	
96	  notifyNativeTimeout = setTimeout(() => {
97	    const payload: any = { action, tabId };
98	
99	    if (action === 'register' && siteName && tools) {
100	      payload.siteName = siteName;
101	      // 使用 WebMCP 标准格式：inputSchema
102	      payload.tools = tools.map((t) => ({
103	        name: t.name,
104	        description: t.description,
105	        inputSchema: t.inputSchema,
106	      }));
107	    }
108	
109	    // Send message via internal message bus (for intra-background communication)
110	    emitBusMessage('forward_to_native', {
111	      type: NativeMessageType.WEBMCP_TOOLS_UPDATE,
112	      payload,
113	    });
114	    console.log(`[WebMCP] Sent tools update to native server: ${action}`);
115	  }, 300);
116	}
117	
118	// API 响应类型 - WebMCP 标准格式
119	interface ApiInputSchema {
120	  type: 'object';
121	  properties: Record<
122	    string,
123	    {
124	      type: string;
125	      description?: string;
126	      enum?: string[];
127	    }
128	  >;
129	  required?: string[];
130	}
131	
132	interface ApiTool {
133	  name: string;
134	  description: string;
135	  inputSchema: ApiInputSchema;
136	  handler: string;
137	}
138	
139	interface ApiSiteConfig {
140	  url_pattern: string;
141	  site_name: string;
142	  tools: ApiTool[];
143	}
144	
145	// 存储当前已注册的网站工具
146	const registeredSiteTools = new Map<number, SiteConfig>();
147	
148	function mergeSiteConfigs(
149	  primary: SiteConfig | null,
150	  secondary: SiteConfig | null,
151	): SiteConfig | null {
152	  if (!primary && !secondary) return null;
153	  if (!primary) return secondary;
154	  if (!secondary) return primary;
155	
156	  const mergedTools: SiteTool[] = [];
157	  const seen = new Set<string>();
158	  for (const tool of [...primary.tools, ...secondary.tools]) {
159	    if (seen.has(tool.name)) continue;
160	    seen.add(tool.name);
161	    mergedTools.push(tool);
162	  }
163	
164	  return {
165	    ...primary,
166	    tools: mergedTools,
167	  };
168	}
169	
170	/**
171	 * 将 API 响应转换为本地 SiteConfig 格式
172	 */
173	function convertApiConfig(apiConfig: ApiSiteConfig): SiteConfig {
174	  return {
175	    urlPattern: new RegExp(apiConfig.url_pattern),
176	    siteName: apiConfig.site_name,
177	    tools: apiConfig.tools.map((t) => ({
178	      name: t.name,
179	      description: t.description,
180	      inputSchema: t.inputSchema,
181	      handler: t.handler,
182	    })),
183	  };
184	}
185	
186	/**
187	 * 从 Worldbook API 获取匹配的站点配置
188	 */
189	async function fetchSiteConfigFromAPI(url: string): Promise<SiteConfig | null> {
190	  try {
191	    const apiUrl = await getWorldbookApiUrl();
192	    const response = await fetch(`${apiUrl}/match?url=${encodeURIComponent(url)}`);
193	    if (!response.ok) {
194	      console.log(`[WebMCP] API request failed: ${response.status}`);
195	      return null;
196	    }
197	    const data = await response.json();
198	    if (!data) return null;
199	    return convertApiConfig(data as ApiSiteConfig);
200	  } catch (error) {
201	    console.log(`[WebMCP] Failed to fetch from API, falling back to local config:`, error);
202	    return null;
203	  }
204	}
205	
206	/**
207	 * Get site config - prefer API, fallback to local config
208	 */
209	async function getSiteConfig(url: string): Promise<SiteConfig | null> {
210	  const recordedConfig = await getLocalRecordedSiteConfig(url);
211	
212	  // Check if Worldbook WebMCP is enabled
213	  const worldbookEnabled = await isWorldbookWebMCPEnabled();
214	
215	  if (worldbookEnabled) {
216	    // Try to fetch from Worldbook API first
217	    const apiConfig = await fetchSiteConfigFromAPI(url);
218	    if (apiConfig) {
219	      console.log(`[WebMCP] Got config from Worldbook API: ${apiConfig.siteName}`);
220	      return mergeSiteConfigs(apiConfig, recordedConfig);
221	    }
222	  } else {
223	    console.log(`[WebMCP] Worldbook WebMCP disabled, skipping API request`);
224	  }
225	
226	  // Fallback to local config if API fails or disabled
227	  const localConfig = matchSiteConfig(url);
228	  if (localConfig) {
229	    console.log(`[WebMCP] Using local config: ${localConfig.siteName}`);
230	  }
231	  return mergeSiteConfigs(localConfig, recordedConfig);
232	}
233	
234	/**
235	 * 初始化 WebMCP 监听器
236	 */
237	export function initWebMCPListener() {
238	  // 监听标签页更新，自动检测并注册工具
239	  chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
240	    if (changeInfo.status === 'complete' && tab.url) {
241	      // Check if we need to unregister old tools (URL changed to non-matching site)
242	      const oldConfig = registeredSiteTools.get(tabId);
243	
244	      const siteConfig = await getSiteConfig(tab.url);
245	      if (siteConfig) {
246	        // Only register if not already registered for this site
247	        if (!oldConfig || oldConfig.siteName !== siteConfig.siteName) {
248	          console.log(`[WebMCP] 检测到匹配的网站: ${siteConfig.siteName} (${tab.url})`);
249	          await registerSiteTools(tabId, siteConfig);
250	
251	          // Notify native server about new tools
252	          notifyNativeServerToolsUpdate('register', tabId, siteConfig.siteName, siteConfig.tools);
253	        }
254	      } else if (oldConfig) {
255	        // URL changed to non-matching site, unregister old tools
256	        console.log(`[WebMCP] 标签页 ${tabId} 导航离开 ${oldConfig.siteName}，清理工具`);
257	        registeredSiteTools.delete(tabId);
258	        notifyNativeServerToolsUpdate('unregister', tabId);
259	      }
260	    }
261	  });
262	
263	  // 监听标签页关闭，清理工具
264	  chrome.tabs.onRemoved.addListener((tabId) => {
265	    if (registeredSiteTools.has(tabId)) {
266	      console.log(`[WebMCP] 标签页 ${tabId} 关闭，清理工具`);
267	      registeredSiteTools.delete(tabId);
268	      notifyNativeServerToolsUpdate('unregister', tabId);
269	    }
270	  });
271	
272	  // 监听消息请求（用于调试和测试）
273	  chrome.runtime.onMessage.addListener((request, _sender, sendResponse) => {
274	    if (request.type === 'webmcp:detect-tools') {
275	      detectAndRegisterTools()
276	        .then((result) => sendResponse({ success: true, result }))
277	        .catch((error) => sendResponse({ success: false, error: error.message }));
278	      return true; // 保持端口打开用于异步响应
279	    }
280	    if (request.type === 'webmcp:call-tool') {
281	      const { tabId, toolName, params } = request;
282	      executeWebMCPTool(tabId, toolName, params || {})
283	        .then((result) => sendResponse({ success: true, ...result }))
284	        .catch((error) => sendResponse({ success: false, error: error.message }));
285	      return true;
286	    }
287	    if (request.type === 'webmcp:list-tools') {
288	      const allTools = getAllRegisteredTools();
289	      const result: any[] = [];
290	      allTools.forEach((config, tid) => {
291	        result.push({
292	          tabId: tid,
293	          siteName: config.siteName,
294	          tools: config.tools.map((t) => t.name),
295	        });
296	      });
297	      sendResponse({ success: true, registeredTools: result });
298	      return true;
299	    }
300	  });
301	
302	  console.log('[WebMCP] Manager initialized');
303	}
