305	/**
306	 * 为标签页注册网站工具
307	 */
308	async function registerSiteTools(tabId: number, siteConfig: SiteConfig) {
309	  try {
310	    // 注入 WebMCP 执行脚本
311	    await chrome.scripting.executeScript({
312	      target: { tabId },
313	      func: injectWebMCPExecutor,
314	      args: [siteConfig.tools.map((t) => ({ name: t.name, handler: t.handler }))],
315	      world: 'MAIN',
316	    });
317	
318	    // 注入桥接脚本用于通信
319	    await chrome.scripting.executeScript({
320	      target: { tabId },
321	      func: injectWebMCPBridge,
322	      world: 'ISOLATED',
323	    });
324	
325	    registeredSiteTools.set(tabId, siteConfig);
326	    console.log(`[WebMCP] 已为标签页 ${tabId} 注册 ${siteConfig.tools.length} 个工具`);
327	  } catch (error) {
328	    console.error(`[WebMCP] 注册工具失败:`, error);
329	  }
