332	/**
333	 * 注入到 MAIN world 的执行器
334	 * 使用 lazy eval + 缓存：只存储 handler 字符串，首次调用时编译并缓存
335	 * 这样既安全（避免 IIFE 在页面加载时执行），又高效（后续调用复用编译结果）
336	 */
337	function injectWebMCPExecutor(tools: Array<{ name: string; handler: string }>) {
338	  // 防止重复注入
339	  if ((window as any).__WEBMCP_EXECUTOR_LOADED__) return;
340	  (window as any).__WEBMCP_EXECUTOR_LOADED__ = true;
341	
342	  // 存储工具 handler 字符串（不立即 eval）
343	  const toolHandlers = new Map<string, string>();
344	  // 缓存编译后的函数
345	  const compiledCache = new Map<string, (...args: unknown[]) => unknown>();
346	
347	  // 只存储 handler 字符串，不编译
348	  tools.forEach((tool) => {
349	    toolHandlers.set(tool.name, tool.handler);
350	    console.log(`[WebMCP] 注册工具: ${tool.name}`);
351	  });
352	
353	  // 监听工具执行请求 (通过 postMessage 从 ISOLATED world)
354	  // 注意：不能使用 async/await，因为 esbuild 会转换成 __async helper，在 MAIN world 中不存在
355	  window.addEventListener('message', (event) => {
356	    if (event.source !== window || event.data?.type !== 'webmcp:execute-tool') return;
357	
358	    const { requestId, toolName, params } = event.data;
359	    console.log(`[WebMCP] 执行工具: ${toolName}`, params);
360	
361	    const handlerCode = toolHandlers.get(toolName);
362	    if (!handlerCode) {
363	      window.postMessage(
364	        {
365	          type: 'webmcp:tool-result',
366	          requestId,
367	          result: null,
368	          error: `工具 ${toolName} 未找到`,
369	        },
370	        '*',
371	      );
372	      return;
373	    }
374	
375	    // Lazy eval + 缓存: 首次调用时编译，后续复用
376	    Promise.resolve()
377	      .then(() => {
378	        let handler = compiledCache.get(toolName);
379	        if (!handler) {
380	          console.log(`[WebMCP] 首次编译工具: ${toolName}`);
381	          handler = eval(`(${handlerCode})`) as (...args: unknown[]) => unknown;
382	          compiledCache.set(toolName, handler);
383	        }
384	        return handler(params);
385	      })
386	      .then((result) => {
387	        window.postMessage(
388	          {
389	            type: 'webmcp:tool-result',
390	            requestId,
391	            result,
392	            error: null,
393	          },
394	          '*',
395	        );
396	      })
397	      .catch((error) => {
398	        window.postMessage(
399	          {
400	            type: 'webmcp:tool-result',
401	            requestId,
402	            result: null,
403	            error: error.message || String(error),
404	          },
405	          '*',
406	        );
407	      });
408	  });
409	
410	  console.log('[WebMCP] Executor initialized with', toolHandlers.size, 'tools');
411	}
