413	/**
414	 * 注入到 ISOLATED world 的桥接脚本
415	 */
416	function injectWebMCPBridge() {
417	  if ((window as any).__WEBMCP_BRIDGE_LOADED__) return;
418	  (window as any).__WEBMCP_BRIDGE_LOADED__ = true;
419	
420	  const pendingRequests = new Map<string, (response: any) => void>();
421	
422	  // 监听来自 background 的消息
423	  chrome.runtime.onMessage.addListener((request, _sender, sendResponse) => {
424	    if (request.type === 'webmcp:call-tool') {
425	      const requestId = `req-${Date.now()}-${Math.random()}`;
426	      pendingRequests.set(requestId, sendResponse);
427	
428	      // 通过 postMessage 转发到 MAIN world
429	      window.postMessage(
430	        {
431	          type: 'webmcp:execute-tool',
432	          requestId,
433	          toolName: request.toolName,
434	          params: request.params,
435	        },
436	        '*',
437	      );
438	
439	      return true; // 异步响应
440	    }
441	  });
442	
443	  // 监听来自 MAIN world 的结果 (通过 postMessage)
444	  window.addEventListener('message', (event) => {
445	    if (event.source !== window || event.data?.type !== 'webmcp:tool-result') return;
446	
447	    const { requestId, result, error } = event.data;
448	    const sendResponse = pendingRequests.get(requestId);
449	    if (sendResponse) {
450	      sendResponse({ result, error });
451	      pendingRequests.delete(requestId);
452	    }
453	  });
454	
455	  console.log('[WebMCP] Bridge initialized');
456	}
