476	function waitForTabLoad(tabId: number, timeout = 15000): Promise<void> {
477	  return new Promise((resolve, reject) => {
478	    const timer = setTimeout(() => {
479	      chrome.tabs.onUpdated.removeListener(listener);
480	      reject(new Error('页面加载超时'));
481	    }, timeout);
482	
483	    const listener = (updatedTabId: number, changeInfo: chrome.tabs.TabChangeInfo) => {
484	      if (updatedTabId === tabId && changeInfo.status === 'complete') {
485	        clearTimeout(timer);
486	        chrome.tabs.onUpdated.removeListener(listener);
487	        // 额外等待一点时间让 JS 执行完成
488	        setTimeout(resolve, 500);
489	      }
490	    };
491	
492	    chrome.tabs.onUpdated.addListener(listener);
493	  });
494	}
