496	/**
497	 * 执行网站工具 - 直接在页面上执行
498	 * 支持 __navigate__ + __then__ 协议用于需要页面跳转的操作
499	 */
500	export async function executeWebMCPTool(
501	  tabId: number,
502	  toolName: string,
503	  params: Record<string, any>,
504	): Promise<{ result: any; error: string | null }> {
505	  const config = registeredSiteTools.get(tabId);
506	  if (!config) {
507	    return { result: null, error: '该标签页没有注册工具' };
508	  }
509	
510	  const tool = config.tools.find((t) => t.name === toolName);
511	  if (!tool) {
512	    return { result: null, error: `工具 ${toolName} 未找到` };
513	  }
514	
515	  try {
516	    // 直接在页面上执行工具 handler
517	    const results = await chrome.scripting.executeScript({
518	      target: { tabId },
519	      world: 'MAIN',
520	      func: (handlerCode: string, toolParams: Record<string, any>) => {
521	        return new Promise((resolve) => {
522	          try {
523	            // Defensive: if params is a string, parse it
524	            const actualParams =
525	              typeof toolParams === 'string' ? JSON.parse(toolParams) : toolParams;
526	
527	            const handler = eval(`(${handlerCode})`);
528	            Promise.resolve(handler(actualParams))
529	              .then((result) => resolve({ result, error: null }))
530	              .catch((err) => resolve({ result: null, error: err.message }));
531	          } catch (e: any) {
532	            resolve({ result: null, error: e.message });
533	          }
534	        });
535	      },
536	      args: [tool.handler, params],
537	    });
538	
539	    if (!results || !results[0]) {
540	      return { result: null, error: '执行失败' };
541	    }
542	
543	    const firstResult = results[0].result as { result: any; error: string | null };
544	
545	    // 检查是否需要导航 + 后续执行
546	    if (firstResult.result && firstResult.result.__navigate__ && firstResult.result.__then__) {
547	      const navigateUrl = firstResult.result.__navigate__;
548	      const thenCode = firstResult.result.__then__;
549	
550	      console.log(`[WebMCP] 导航到: ${navigateUrl}`);
551	
552	      // 导航到目标 URL
553	      await chrome.tabs.update(tabId, { url: navigateUrl });
554	
555	      // 等待页面加载完成
556	      await waitForTabLoad(tabId);
557	
558	      console.log(`[WebMCP] 页面加载完成，执行后续代码`);
559	
560	      // 重新注册工具到新页面
561	      const newTab = await chrome.tabs.get(tabId);
562	      if (newTab.url) {
563	        const newConfig = await getSiteConfig(newTab.url);
564	        if (newConfig) {
565	          await registerSiteTools(tabId, newConfig);
566	        }
567	      }
568	
569	      // 执行后续代码
570	      const thenResults = await chrome.scripting.executeScript({
571	        target: { tabId },
572	        world: 'MAIN',
573	        func: (code: string) => {
574	          return new Promise((resolve) => {
575	            try {
576	              const result = eval(code);
577	              Promise.resolve(result)
578	                .then((r) => resolve({ result: r, error: null }))
579	                .catch((err) => resolve({ result: null, error: err.message }));
580	            } catch (e: any) {
581	              resolve({ result: null, error: e.message });
582	            }
583	          });
584	        },
585	        args: [thenCode],
586	      });
587	
588	      if (thenResults && thenResults[0]) {
589	        return thenResults[0].result as { result: any; error: string | null };
590	      }
591	      return { result: null, error: '后续执行失败' };
592	    }
593	
594	    return firstResult;
595	  } catch (error: any) {
596	    return { result: null, error: error.message };
597	  }
598	}
